import sqlite3, csv
con = sqlite3.connect('db/satscores.db')
schools = {}
for r in con.execute('SELECT cds, sname, AvgScrMath FROM satscores WHERE dname LIKE "%Riverside%" AND sname IS NOT NULL AND AvgScrMath IS NOT NULL'):
    cds, sname, score = r
    if cds not in schools: schools[cds] = {'name': sname, 'scores': []}
    schools[cds]['scores'].append(score)
con.close()
avgs = [(cds, sum(s['scores'])/len(s['scores']), s['name']) for cds, s in schools.items() if sum(s['scores'])/len(s['scores']) > 400]
with open('csv/frpm.csv') as f:
    frpm = {row['CDSCode']: row.get('Charter Funding Type', '') for row in csv.DictReader(f)}
for cds, avg, name in sorted(avgs, key=lambda x: -x[1]):
    funding = frpm.get(cds, '')
    print(f"{name}: avg={avg:.2f}, funding='{funding}'")

